// Purpose: Resolve the exact top-level Finance Evidence state and fail closed.
const contract = $('Setup Parameters').first().json;
const expectedName = 'Finance Evidence';
if (contract.contract_version !== 'ONEDRIVE_FINANCE_EVIDENCE_ROOT_SETUP_V1'
    || contract.root_folder_name !== expectedName
    || contract.expected_parent_scope !== 'root'
    || contract.create_if_absent !== true
    || contract.receipt_mode !== 'REDACTED') {
    throw new Error('ONEDRIVE_ROOT_SETUP_CONTRACT_MISMATCH');
}
if (expectedName.includes('/') || expectedName.includes('\\') || expectedName.trim() !== expectedName) {
    throw new Error('ONEDRIVE_ROOT_FOLDER_NAME_INVALID');
}
const rows = $input.all().map(item => item.json).filter(row => row && row.id);
const sameName = rows.filter(row => String(row.name || '').toLocaleLowerCase('en-US') === expectedName.toLocaleLowerCase('en-US'));
const nonFolders = sameName.filter(row => !row.folder);
if (nonFolders.length) {
    throw new Error('ONEDRIVE_ROOT_NAME_OCCUPIED_BY_NON_FOLDER');
}
const caseVariants = sameName.filter(row => String(row.name) !== expectedName);
if (caseVariants.length) {
    throw new Error('ONEDRIVE_ROOT_FOLDER_CASE_MISMATCH');
}
const exactFolders = sameName.filter(row => row.folder && String(row.name) === expectedName);
if (exactFolders.length > 1) {
    throw new Error('ONEDRIVE_ROOT_FOLDER_DUPLICATE_EXACT_MATCH');
}
if (exactFolders.length === 1) {
    return [{ json: { action: 'REUSE_EXISTING', existing_folder_id: String(exactFolders[0].id) } }];
}
return [{ json: { action: 'CREATE_REQUIRED', existing_folder_id: null } }];

// Purpose: Verify the exact root folder after the create-or-reuse decision.
const expectedName = $('Setup Parameters').first().json.root_folder_name;
const decision = $('Resolve Existing Root State').first().json;
const rows = $input.all().map(item => item.json).filter(row => row && row.id);
const sameName = rows.filter(row => String(row.name || '').toLocaleLowerCase('en-US') === expectedName.toLocaleLowerCase('en-US'));
if (sameName.some(row => !row.folder)) {
    throw new Error('ONEDRIVE_ROOT_READBACK_NON_FOLDER_CONFLICT');
}
if (sameName.some(row => String(row.name) !== expectedName)) {
    throw new Error('ONEDRIVE_ROOT_READBACK_CASE_MISMATCH');
}
const exactFolders = sameName.filter(row => row.folder && String(row.name) === expectedName);
if (exactFolders.length !== 1 || !exactFolders[0].id) {
    throw new Error(`ONEDRIVE_ROOT_READBACK_EXACT_COUNT_MISMATCH:${exactFolders.length}`);
}
const observedId = String(exactFolders[0].id);
if (decision.action === 'REUSE_EXISTING' && observedId !== decision.existing_folder_id) {
    throw new Error('ONEDRIVE_ROOT_REUSE_ID_DRIFT');
}
if (decision.action === 'CREATE_REQUIRED') {
    const created = $('Create Finance Evidence at Drive Root').first().json;
    if (!created.folder || String(created.name) !== expectedName || String(created.id || '') !== observedId) {
        throw new Error('ONEDRIVE_ROOT_CREATE_READBACK_MISMATCH');
    }
}
return [{
    json: {
        root_folder_id: observedId,
        root_folder_name: expectedName,
        action: decision.action === 'CREATE_REQUIRED' ? 'CREATED' : 'REUSED',
    },
}];

// Purpose: Reject Finance Evidence/Finance Evidence and emit a redacted setup receipt.
const verified = $('Verify Exact Root Readback').first().json;
const children = $input.all().map(item => item.json).filter(row => row && row.id);
const nestedSameName = children.filter(row => row.folder
    && String(row.name || '').toLocaleLowerCase('en-US') === verified.root_folder_name.toLocaleLowerCase('en-US'));
if (nestedSameName.length) {
    throw new Error(`ONEDRIVE_NESTED_FINANCE_EVIDENCE_DUPLICATION_DETECTED:${nestedSameName.length}`);
}
return [{
    json: {
        schema_version: 'onedrive-finance-evidence-root-setup-receipt-v1',
        status: 'VERIFIED',
        action: verified.action,
        folder_name: verified.root_folder_name,
        parent_scope: 'root',
        exact_root_match_count: 1,
        nested_same_name_folder_count: 0,
        folder_id_present: Boolean(verified.root_folder_id),
        folder_id_redacted: true,
        credential_values_recorded: false,
        drive_metadata_recorded: false,
        file_contents_recorded: false,
        production_workflows_activated: false,
        actual_writes: false,
        cashback_writes: false,
        provider_mutation_scope: verified.action === 'CREATED'
            ? 'CREATE_SINGLE_ONEDRIVE_ROOT_FOLDER'
            : 'NONE',
        verified_at: new Date().toISOString(),
    },
}];
